def max_sum_restricted(total_rows, max_val, exclude_k, exclude_nk):
    available_ks = []
    for k in range(1, max_val + 1):
        n_k = max_val // k
        if k == exclude_k:
            n_k = exclude_nk
        available_ks.extend([k] * n_k)

    available_ks.sort(reverse=True)
    return sum(available_ks[:total_rows])

print(max_sum_restricted(198, 200, 100, 0))

